#!/usr/bin/env node
/**
 * Token usage audit — flags a raw hex colour / px / rem / em literal in an override component
 * or theme recipe, where a Zimmermann token (a foundation constant, a var(--zimm-*) reference,
 * or a Chakra prop resolving through a registered scale) should be used instead.
 *
 * Usage:
 *   node scripts/auditTokenUsage.mjs
 *
 * Scope: overrides/app/components/** and overrides/app/theme/components/** — .ts/.tsx/.scss.
 * Deliberately excludes:
 *   - overrides/app/theme/foundation/ — not under either scan root; these files ARE the source
 *     of truth, so a raw value there is the point, not a violation.
 *   - *.test.ts(x) and *.stories.tsx — test assertions and Storybook demo code routinely need
 *     illustrative/representative raw values that aren't "a hardcoded design value shipped to
 *     production" in the sense this audit cares about (testing.md already treats these
 *     differently from production styling rigor).
 *
 * A match is downgraded from a failure to an ACKNOWLEDGED exception (still printed, does not
 * affect the exit code) when the contiguous non-blank block of lines ending at the match — i.e.
 * the match's own line plus every line above it up to the nearest blank line or file start —
 * contains "provisional", "pending", "placeholder", or an explicit "audit-allow". This is the
 * exact vocabulary this codebase already uses for every documented raw-value exception today
 * (e.g. zimmButton.css.ts's BTN_HEIGHT_LG/BTN_HEIGHT_SM/BTN_PADDING_Y, footer.css.ts's
 * SPACE_SECTION/SIZE_COL_SUB/SIZE_COL_MAP). Reading the existing explanatory comment as the
 * allow-list entry avoids a second, separately-maintained list that would drift from the code
 * the moment either one changes.
 *
 * The "nearest blank line" boundary, not a fixed line count, matters: this codebase's real
 * exception comments are often a shared multi-line block covering several sibling declarations
 * (footer.css.ts's four provisional constants share one comment), or wrap the marker word
 * itself across a line break (zimmSubscribeSection.css.ts had "...52/40. Pending\n// Kiera."
 * — "Pending" and "Kiera" on different lines). A fixed N-line window missed both shapes during
 * this script's own first calibration pass against the real codebase.
 *
 * This is a line-based grep, not an AST parse — matches
 * .claude/rules/overrideStyling.md's own framing ("it greps for exactly this"). A real
 * false-positive class this cannot fully rule out: a hex-looking string in a non-colour
 * context (e.g. a URL fragment that happens to be 3-8 hex characters) would still be flagged;
 * mark it with `// audit-allow: <reason>` rather than trying to make the regex smarter.
 *
 * Not wired into CI yet — see overrideStyling.md's note on why (someone needs to own triaging
 * false positives on a real run first).
 */

import { readFileSync, readdirSync, existsSync } from 'fs';
import { join, extname, relative, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, '..');
const APP = join(ROOT, 'overrides/app');

const SCAN_ROOTS = [join(APP, 'components'), join(APP, 'theme/components')];
const SCAN_EXTENSIONS = new Set(['.ts', '.tsx', '.scss']);

const HEX_RE = /#[0-9a-fA-F]{3,8}\b/g;
const UNIT_RE = /\b\d+(?:\.\d+)?(?:rem|em|px)\b/g;
const EXCEPTION_MARKER_RE = /provisional|pending|placeholder|audit-allow/i;

const isExcludedFile = (filePath) =>
  filePath.endsWith('.test.ts') || filePath.endsWith('.test.tsx') || filePath.endsWith('.stories.tsx');

function walk(dir, files = []) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) {
      walk(full, files);
    } else if (SCAN_EXTENSIONS.has(extname(entry.name)) && !isExcludedFile(full)) {
      files.push(full);
    }
  }
  return files;
}

/**
 * Strips `//` and `/* *\/` comment content from a line so a Figma hex value or px measurement
 * mentioned in prose doesn't get flagged as a code violation. Tracks block-comment state across
 * lines via the mutable `state` object the caller owns. `//` is only treated as a comment start
 * when not immediately preceded by `:` — otherwise `'https://wa.me/...'` string literals (real
 * content in this codebase's Contentful fixtures) would truncate the line early.
 */
function stripComments(line, state) {
  let result = '';
  let i = 0;
  while (i < line.length) {
    if (state.inBlockComment) {
      const end = line.indexOf('*/', i);
      if (end === -1) return result;
      i = end + 2;
      state.inBlockComment = false;
      continue;
    }
    if (line[i] === '/' && line[i + 1] === '/' && line[i - 1] !== ':') break;
    if (line[i] === '/' && line[i + 1] === '*') {
      state.inBlockComment = true;
      i += 2;
      continue;
    }
    result += line[i];
    i += 1;
  }
  return result;
}

function scanFile(filePath) {
  const relPath = relative(ROOT, filePath);
  const lines = readFileSync(filePath, 'utf8').split('\n');
  const state = { inBlockComment: false };
  const findings = [];

  lines.forEach((rawLine, idx) => {
    const lineNo = idx + 1;
    const code = stripComments(rawLine, state);

    const matches = [...code.matchAll(HEX_RE), ...code.matchAll(UNIT_RE)];
    if (matches.length === 0) return;

    let contextStart = idx;
    while (contextStart > 0 && lines[contextStart - 1].trim() !== '') contextStart -= 1;

    while (contextStart > 0 && lines[contextStart - 1].trim() !== '') contextStart -= 1;
    const context = lines.slice(contextStart, idx + 1).join('\n');
    const acknowledged = EXCEPTION_MARKER_RE.test(context);

    for (const match of matches) {
      findings.push({ file: relPath, line: lineNo, value: match[0], acknowledged, text: rawLine.trim() });
    }
  });

  return findings;
}

const files = SCAN_ROOTS.filter(existsSync).flatMap((root) => walk(root));
const allFindings = files.flatMap(scanFile);
const failures = allFindings.filter((f) => !f.acknowledged);
const acknowledged = allFindings.filter((f) => f.acknowledged);

console.log('Token usage audit');
console.log('==================');
console.log(`Scanned ${files.length} file(s) under overrides/app/components/ and overrides/app/theme/components/\n`);

if (failures.length > 0) {
  console.log(`❌ ${failures.length} raw value(s) with no acknowledged exception:\n`);
  for (const f of failures) {
    console.log(`  ${f.file}:${f.line}  '${f.value}'`);
    console.log(`    ${f.text}`);
  }
  console.log('\n  Reach for a token instead — var(--zimm-color-*) for hex, var(--zimm-scale-*) for px/rem/em.');
  console.log(
    '  If this genuinely has no token yet (pending UI-designer sign-off), name it as a constant\n' +
      '  with a comment containing "provisional"/"pending"/"placeholder", or add "audit-allow: <reason>".',
  );
}

if (acknowledged.length > 0) {
  console.log(`\n✓ ${acknowledged.length} raw value(s) with an acknowledged exception (not failing):`);
  for (const f of acknowledged) {
    console.log(`  ${f.file}:${f.line}  '${f.value}'`);
  }
}

console.log(
  failures.length > 0
    ? `\n${failures.length} unacknowledged violation(s) found.`
    : '\nNo unacknowledged raw hex/px/rem/em literals found.',
);

process.exit(failures.length > 0 ? 1 : 0);

18: *   3. A recipe key that collides with a base SFCC recipe. `theme/index.ts` composes with
347:  test('no recipe silently inherits a base SFCC recipe of the same name', () => {
348:    // extendTheme DEEP MERGES. These three intentionally share a base key: Button wants the
350:    // parts we still rely on. Anything else must be namespaced (e.g. ZimmFooter, not Footer).
351:    const INTENTIONAL_MERGES = ['Button', 'Header', 'ListMenu'];
354:      .filter((name) => !INTENTIONAL_MERGES.includes(name))
=== tail ===
 * shape, on any of these (`top: floated ? '3xs' : '50%'` in zimmTextInput.css.ts), so
 * resolving with only the all-false default can leave a branch's value completely unwalked —
 * '3xs' shipped exactly this way: `floated` is false under the all-default combo, so the
 * guard below never saw the string it was meant to catch. Exhaustive, not sampled: n is
 * small enough that 2^n costs nothing, and a missed combination is the whole failure mode.
 */
const booleanKeys = Object.keys(DEFAULT_STYLE_PROPS).filter((k) => typeof DEFAULT_STYLE_PROPS[k] === 'boolean');
const PROP_COMBINATIONS: Record<string, unknown>[] = Array.from({ length: 2 ** booleanKeys.length }, (_, i) => {
  const combo = { ...DEFAULT_STYLE_PROPS };
  booleanKeys.forEach((key, bit) => {
    combo[key] = Boolean(i & (1 << bit));
  });
  return combo;
});

/** baseStyle may be a plain object or a function of props (see zimmTextInput). Resolves with
 *  the all-false default only — for checks that need just the structural shape (which part
 *  keys exist), not every value a branch could produce. */
const resolveBaseStyle = (recipe: Record<string, unknown>): unknown => {
  const bs = recipe.baseStyle;
  if (typeof bs !== 'function') return bs;
  return (bs as (p: Record<string, unknown>) => unknown)(DEFAULT_STYLE_PROPS);
};

/** Every value a function-form baseStyle can produce, across every prop combination. A
 *  plain-object baseStyle has only the one "combination" (itself). The value-level guards
 *  below walk this, not resolveBaseStyle's single default resolution — see PROP_COMBINATIONS. */
const resolveAllBaseStyles = (recipe: Record<string, unknown>): unknown[] => {
  const bs = recipe.baseStyle;
  if (typeof bs !== 'function') return [bs];
  return PROP_COMBINATIONS.map((props) => (bs as (p: Record<string, unknown>) => unknown)(props));
};

const collect = (): Found[] => {
  const found: Found[] = [];
  for (const [name, recipe] of Object.entries(components)) {
    const r = recipe as unknown as Record<string, unknown>;
    for (const resolved of resolveAllBaseStyles(r)) {
      walk(resolved, name, '', '', (f) => found.push(f));
    }
    for (const section of [r.variants, r.sizes]) {
      walk(section, name, '', '', (f) => found.push(f));
    }
  }
  // resolveAllBaseStyles calls a function-form baseStyle once per prop combination (32
  // today), and most lines don't depend on the varying prop at all — the same Found would
  // otherwise appear dozens of times in a failing test's offender list.
  const seen = new Set<string>();
  return found.filter((f) => {
    const key = where(f);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
};

describe('recipe guards', () => {
  test('collect() actually walks the registered recipes', () => {
    // Every other test here asserts an empty offender list, which an empty input satisfies
    // just as well as a clean one. Without this, deleting `components` would turn the whole
    // file green.
    expect(Object.keys(components).length).toBeGreaterThan(0);
    expect(collect().length).toBeGreaterThan(0);
  });

  test('no sizing property uses a bare spacing-scale key', () => {
    const offenders = collect()
      .filter((f) => SIZING_PROPS.has(f.prop) && SPACING_KEYS.includes(f.value))
      .map(where);

    // `width: 'xl'` reads theme.sizes.xl (36rem), not space.xl (1.5rem).
    // Use var(--zimm-scale-*), an imported constant, or an explicit unit instead.
    expect(offenders).toEqual([]);
  });

  test('no typography property uses a bare scale key', () => {
    const offenders = collect()
      .filter((f) => TYPOGRAPHY_PROPS.get(f.prop)?.has(f.value) ?? false)
      .map(where);

    // `fontSize: '2xs'` reads Chakra's fontSizes (10px), not the Zimmermann scale (14px);
    // `lineHeight: '2xs'` resolves to nothing at all. Use textStyle or var(--zimm-font-*).
    expect(offenders).toEqual([]);
  });

  test('no compound shorthand contains a bare scale key', () => {
    const offenders = collect()
      .filter((f) => {
        if (!SPACE_SHORTHANDS.has(f.prop)) return false;
        if (!f.value.includes(' ')) return false; // single token is fine
        // Split on whitespace outside var(...) and look for a bare scale key.
        const parts = f.value.replace(/var\([^)]*\)/g, 'VAR').split(/\s+/);
        return parts.some((part) => SPACING_KEYS.includes(part));
      })
      .map(where);

    // Chakra resolves a token only as a whole value. `padding: 'xs 0'` is emitted verbatim
    // and the browser drops the declaration. Use paddingY/paddingX or a var() instead.
    expect(offenders).toEqual([]);
  });

  test('no override-component style uses a bare token key on a registered scale', () => {
    const offenders = collect()
      .filter(
        (f) =>
          (SPACE_PROPS.has(f.prop) && SPACING_KEYS.includes(f.value)) || (COLOR_PROPS.has(f.prop) && COLOR_KEYS.has(f.value)),
      )
      .map(where);

    // Not a wrong-value bug — space and colors ARE registered Chakra scales, so `gap: 'xs'` and
    // `color: 'text.inverse'` already resolve to the correct Zimmermann value. House style
    // instead: use var(--zimm-scale-*) / var(--zimm-color-*) so every call site is an
    // unambiguous zimm reference, not something a reviewer has to check against theme/index.ts's
    // registered-scale list to know whether it's correct.
    expect(offenders).toEqual([]);
  });

  test('no recipe silently inherits a base SFCC recipe of the same name', () => {
    // extendTheme DEEP MERGES. These three intentionally share a base key: Button wants the
    // base variants, and Header/ListMenu are partial overrides of components whose other
    // parts we still rely on. Anything else must be namespaced (e.g. ZimmFooter, not Footer).
    const INTENTIONAL_MERGES = ['Button', 'Header', 'ListMenu'];

    const unexpected = Object.keys(components)
      .filter((name) => !INTENTIONAL_MERGES.includes(name))
      .filter((name) => {
        const ours = resolveBaseStyle(components[name as keyof typeof components] as never) ?? {};
        const merged = resolveBaseStyle((theme.components?.[name] ?? {}) as Record<string, unknown>) ?? {};
        const ourKeys = new Set(Object.keys(ours as object));
        // A key present after composition that we never declared came from the base theme.
        return Object.keys(merged as object).some((k) => !ourKeys.has(k));
      });

    expect(unexpected).toEqual([]);
  });
});

1	/**
2	 * Guard: a multipart recipe's declared `parts` must cover every part the component actually
3	 * reads off `useMultiStyleConfig`.
4	 *
5	 * The failure this catches is silent, though not by the mechanism it looks like: `parts` does
6	 * not gate `baseStyle`. Probed directly against `ChakraProvider`, a recipe declaring
7	 * `parts: ['declared']` while carrying both parts in `baseStyle` and in a variant resolves to
8	 * `{declared: {...base, ...variant}, undeclared: {...base}}` — the undeclared part keeps its
9	 * full base styling and loses only the variant's. `parts` gates `variants`/`sizes`. The base
10	 * SFCC `theme/components/project/header.js` is that same shape shipping in production: 9
11	 * declared `parts` against 13 `baseStyle` keys, and the four it omits (`accountIcon`,
12	 * `arrowDown`, `signoutIcon`, `signoutText`) are each read, spread and styled by
13	 * `components/header/index.jsx` (lines 232, 255, 321, 323) today.
14	 *
15	 * So an undeclared part goes wrong in one of two ways, both quiet. If `baseStyle` covers it, it
16	 * renders correctly and then stops responding to variants and sizes — latent on a recipe with no
17	 * variants today, surfacing only the day someone adds one. If `baseStyle` does not, the read is
18	 * `undefined`, `__css={undefined}` is a legal prop, and the element inherits. Neither is reported
19	 * by `tsc`, eslint, an axe run, or a `play` that only asserts text. The first case is precisely
20	 * the "would survive a refactor invisibly if broken" case .claude/rules/testing.md says to cover,
21	 * so the corrected mechanism strengthens this guard's justification rather than weakening it.
22	 *
23	 * Comparing `parts` against the recipe's own `baseStyle` keys would not catch it: renaming a
24	 * part in both places at once keeps them consistent with each other and still breaks the
25	 * component. The component's reads are the only source of truth for what it needs, so this
26	 * walks the component source.
27	 *
28	 * Scope: `overrides/app/components/**` — every co-located `<name>.css.ts`, which since the
29	 * footer decomposition is where a component's recipe normally lives.
30	 *
31	 * It is not a whole-repo guard, and nothing else covers the remainder: the model is strictly
32	 * sibling-based (a recipe's `parts` are reconciled against the `index.tsx` beside it), so a
33	 * recipe that does not sit next to its component is out of reach. `theme/components/header.ts`
34	 * is the only multipart recipe in that position today and is therefore unguarded.
35	 * `theme/components/recipeGuards.test.ts` does not pick it up either — that suite has no
36	 * parts-vs-reads check of any kind; it guards bare token keys and recipe namespacing.
37	 *
38	 * `READ_RE` recognises only the identifier `styles`, so a second binding in the same component
39	 * is invisible here: `zimmSubscribeModal/index.tsx` reads `chrome.actions`. That one is
40	 * deliberately out of scope rather than a gap to close — `chrome` holds *ZimmModal's* recipe,
41	 * so the sibling model would misattribute `actions` to `zimmSubscribeModal.css.ts`, which
42	 * correctly does not declare it.
43	 */
44	import { describe, expect, test } from 'vitest';
45	import { existsSync, readFileSync, readdirSync } from 'node:fs';
46	import path from 'node:path';
47	
48	const COMPONENTS = path.resolve(process.cwd(), 'overrides/app/components');
49	
50	const walk = (dir: string): string[] =>
51	  readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
52	    const full = path.join(dir, entry.name);
53	    return entry.isDirectory() ? walk(full) : [full];
54	  });
55	
56	/** `parts: ['root', 'label']` — the literal array in a `.css.ts` recipe. */
57	const PARTS_RE = /\bparts:\s*\[([^\]]*)\]/;
58	/** `styles.label` and `styles['label']`, the two ways a component reads a resolved part. */
59	const READ_RE = /\bstyles(?:\.([A-Za-z][A-Za-z0-9]*)|\[\s*'([^']+)'\s*\])/g;
60	
61	type MultipartRecipe = {
62	  name: string;
63	  recipeFile: string;
64	  componentFile: string;
65	  declared: string[];
66	  read: string[];
67	  /**
68	   * Whether the sibling component was found. Recorded rather than thrown on: reading a missing
69	   * file here would fail *collection*, and vitest reports that as one error for the whole file
70	   * — taking the vacuity guard below down with it. A guard that disappears when its own
71	   * assumption breaks is the exact failure this suite exists to prevent.
72	   */
73	  componentFound: boolean;
74	};
75	
76	const collectMultipartRecipes = (): MultipartRecipe[] =>
77	  walk(COMPONENTS)
78	    .filter((file) => file.endsWith('.css.ts'))
79	    .flatMap((recipeFile) => {
80	      const declaredMatch = PARTS_RE.exec(readFileSync(recipeFile, 'utf8'));
81	      if (!declaredMatch) return []; // single-part recipe — nothing to reconcile
82	
83	      const declared = declaredMatch[1]
84	        .split(',')
85	        .map((entry) => entry.trim().replace(/^['"]|['"]$/g, ''))
86	        .filter(Boolean);
87	
88	      const componentFile = path.join(path.dirname(recipeFile), 'index.tsx');
89	      const componentFound = existsSync(componentFile);
90	      const read = componentFound
91	        ? [...readFileSync(componentFile, 'utf8').matchAll(READ_RE)].map((match) => match[1] ?? match[2])
92	        : [];
93	
94	      return [
95	        { name: path.basename(recipeFile, '.css.ts'), recipeFile, componentFile, declared, read, componentFound },
96	      ];
97	    });
98	
99	const recipes = collectMultipartRecipes();
100	
101	describe('multipart recipes declare every part their component reads', () => {
102	  test.each(recipes.map((recipe) => [recipe.name, recipe] as const))('%s', (_name, recipe) => {
103	    expect(recipe.componentFound, `no component found at ${recipe.componentFile} for ${recipe.recipeFile}`).toBe(true);
104	    const undeclared = [...new Set(recipe.read)].filter((part) => !recipe.declared.includes(part));
105	    expect(undeclared, `${recipe.componentFile} reads parts absent from ${recipe.recipeFile}`).toEqual([]);
106	  });
107	
108	  // Vacuity guard. A suite built by walking the filesystem passes trivially when the walk
109	  // returns nothing — a moved directory or a renamed suffix would turn this file into a
110	  // no-op that still reports green. Mirrors recipeGuards.test.ts's own self-test.
111	  test('the walk actually collected something', () => {
112	    expect(walk(COMPONENTS).length).toBeGreaterThan(0);
113	    expect(recipes.length).toBeGreaterThan(0);
114	    expect(recipes.every((recipe) => recipe.declared.length > 0)).toBe(true);
115	    expect(recipes.some((recipe) => recipe.read.length > 0)).toBe(true);
116	  });
117	});
