export type FooterConfigEntry = {
  sys: {
    id: string;
    contentType: { sys: { id: 'footerConfig' } };
  };
  fields: {
    internalTitle: string;
    subscribeHeading?: string;
    subscribeBody?: string;
    // Read-only both ways. The footer only ever .maps these, but footer/index.stories.content.ts's
    // FOOTER_FIXTURE is a plain module singleton multiple stories in index.stories.tsx read
    // directly, so an in-place push/sort/index-assign anywhere would corrupt every other
    // story reading the same object. ReadonlyArray blocks push/pop/splice/sort/reverse/
    // index-assign/length; the `readonly` property modifier additionally blocks swapping the
    // whole array out. Matches BottomBarProps.legalLinks in footer/index.tsx, which already
    // types its array as ReadonlyArray<>.
    readonly navGroups: ReadonlyArray<FooterNavGroupEntry>;
