import { afterEach, beforeEach, describe, test, expect, vi } from 'vitest';
import { resolveBorderColour, resolveHoverBorderColour, resolveLabelColour, ZimmTextInput } from './zimmTextInput.css';
import type { ZimmTextInputStyleProps } from './zimmTextInput.css';

/**
 * The Figma colour cascade is the part of this recipe that can break without surfacing as a
 * type or build error — a mis-ordered branch renders a plausible-but-wrong border. These
 * assertions moved here from useZimmTextInputState.test.ts when the derivation moved out of
 * the hook and into the theme.
 */

// .claude/rules/testing.md asks for beforeEach setup and vi.clearAllMocks() after each test.
// The resolvers here are pure and this file mocks nothing, so these hooks are a convention
// baseline rather than load-bearing isolation — kept so the file matches the rule as written
// and stays correct if a mock is ever introduced.
let base: ZimmTextInputStyleProps;

beforeEach(() => {
  base = { inverse: false, disabled: false, hasError: false, focused: false, filled: false };
});

afterEach(() => {
  vi.clearAllMocks();
});

describe('ZimmTextInput — border colour precedence', () => {
  test('disabled wins over error and filled', () => {
    expect(resolveBorderColour({ ...base, disabled: true, hasError: true, filled: true })).toBe(
      'var(--zimm-color-border-forms)',
    );
  });

  test('error wins over focus and filled', () => {
    expect(resolveBorderColour({ ...base, hasError: true, filled: true })).toBe('var(--zimm-color-status-error)');
  });

  test('a filled but unfocused field darkens to the focus colour', () => {
    expect(resolveBorderColour({ ...base, filled: true })).toBe('var(--zimm-color-border-focus)');
  });

